import java.util.concurrent.ConcurrentHashMap;
import java.util.function.BiFunction;

public class AUTask4 {
    public static ConcurrentHashMap<String, Integer> countWords(String[] words) {
        ConcurrentHashMap<String, Integer> map = new ConcurrentHashMap<>();
        for (String w : words) {
            map.merge(w, 1, Integer::sum);
        }
        return map;
    }

    public static ConcurrentHashMap<String, Integer> computeIfPresentDouble(
            ConcurrentHashMap<String, Integer> map, String key) {
        map.computeIfPresent(key, (k, v) -> v * 2);
        return map;
    }

