        "(?<timestamp>\\d{4}-\\d{2}-\\d{2})\\s+(?<level>WARN|ERROR|INFO)\\s+(?<msg>.+)",
        Pattern.CASE_INSENSITIVE | Pattern.DOTALL
    );

    public static Map<String, String> parseLogEntry(String line) {
        Matcher m = LOG_PATTERN.matcher(line);
        Map<String, String> result = new LinkedHashMap<>();
        if (m.matches()) {
