    public static int[] bitSetToSortedArray(BitSet bs) {
        int[] result = new int[bs.cardinality()];
        int idx = 0;
        for (int i = bs.nextSetBit(0); i >= 0; i = bs.nextSetBit(i + 1)) {
            result[idx++] = i;
        }
        return result;
    }

    public static void main(String[] args) {
        BitSet mask = createBitMask(new int[]{5, 1, 3, 1, 7});
        // BitSet deduplicates — setting bit 1 twice has no effect
        assert mask.cardinality() == 4 : "Expected 4 unique bits";
        assert mask.get(1) && mask.get(3) && mask.get(5) && mask.get(7);
        assert !mask.get(0) && !mask.get(2) && !mask.get(4) && !mask.get(6);

