        // BitSet grows dynamically — no IndexOutOfBoundsException
        mask.set(1000);
        assert mask.get(1000);
        assert mask.cardinality() == 5;

        int[] sorted = bitSetToSortedArray(mask);
        assert sorted[0] == 1 && sorted[1] == 3 && sorted[2] == 5;
        assert sorted[3] == 7 && sorted[4] == 1000;
        System.out.println("Task 44 OK");
    }
