public class AUTask45 {
    public static String runCommand(String... command) throws Exception {
        ProcessBuilder pb = new ProcessBuilder(command);
        pb.redirectErrorStream(true);
        pb.environment().put("LANG", "en_US.UTF-8");
        Process proc = pb.start();
        StringBuilder sb = new StringBuilder();
        try (BufferedReader reader = new BufferedReader(
                new InputStreamReader(proc.getInputStream()))) {
            String line;
            while ((line = reader.readLine()) != null) {
                sb.append(line).append("\n");
            }
        }
        boolean finished = proc.waitFor(30, TimeUnit.SECONDS);
        if (!finished) {
            proc.destroyForcibly();
            throw new RuntimeException("Process timed out after 30 seconds");
        }
        int exitCode = proc.exitValue();
        if (exitCode != 0) {
            throw new RuntimeException("Exit code: " + exitCode + ", output: " + sb);
        }
        return sb.toString().trim();
    }

